  set pack_id = excluded.pack_id,
      name = excluded.name,
      job = excluded.job,
      repeats_when = excluded.repeats_when,
      is_desk = excluded.is_desk,
      sort_order = excluded.sort_order,
      grok_template_url = excluded.grok_template_url;
